sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    /*** Storing the current and previous value of field from the Business Process Instance record ***/
    var previousCoreEventStatus = previous.core_stage_reference;
    var currentCoreEventStatus = current.core_stage_reference;
    var tradeIDValue = current.trade_id;
    var caseClosureCheck = current.core_stage_reference.previous_case_closure_stage;
    var caseQuery;
    var bpDataCore = current.core_stage_reference.business_process;
    try {
        /**** Core  ****/
        if (currentCoreEventStatus != previousCoreEventStatus) { // updating Business Process Stage and Custody Case table Query condition for Core
            caseQuery = 'active=true^trade_id=' + tradeIDValue + '^triggered_by.business_process=' + bpDataCore + '^amend_caseNOT INconfSettle,True';   // amend_case is set 'True' in Amend Flow for linked case, added as part of MSSCUSTODY-6538
        }

        /***Query Case and Task only if Previpus Case Closure is true **/
        if (caseClosureCheck) {
            var grCustodyCase = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case');
            grCustodyCase.addEncodedQuery(caseQuery);
            grCustodyCase.query();
            while (grCustodyCase.next()) {
                var grFlow = new GlideRecord('sys_flow_context'); // Cancelling the flow context when the case is closing as part of FOL Event
                grFlow.addQuery('source_record', grCustodyCase.sys_id);
                grFlow.query();
                while (grFlow.next()) {
                    sn_fd.FlowAPI.cancel(grFlow.sys_id, 'Cancelling active flows for active false custody cases');
                    gs.info("this cancels the flow");
                }
                grCustodyCase.state = 3; // Updating state of  the Case to "Closed Complete" after either the flow
                grCustodyCase.update();
            }
            current.is_case_created_core = false; //set flag to false
        }

    } catch (ex) {
        gs.addInfoMessage(ex.message);
    }

})(current, previous);
